const csv = msg.payload;
const unitId = msg.unitId;

// Parse CSV response from InfluxDB
const results = {};
try {
    const lines = csv.split('\n').filter(l => l && !l.startsWith('#') && !l.startsWith(',result'));
    for (const line of lines) {
        const cols = line.split(',');
        if (cols.length >= 4) {
            const field = cols[cols.length - 2];
            const value = parseFloat(cols[cols.length - 1]);
            if (field && !isNaN(value)) results[field] = value;
        }
    }
} catch(e) { node.warn('CSV parse error: ' + e.message); }

// Use parsed values or safe defaults
const tempFirst     = results.tempFirst    ?? 4.0;
const tempLast      = results.tempLast     ?? 4.0;
const tempMean      = results.tempMean     ?? 4.0;
const energyMean    = results.energyMean   ?? 2.0;
const compTotal     = results.compTotal    ?? 1;
const compOn        = results.compOn       ?? 0;

// --- Temperature stability score (0-100, lower = worse) ---
const tempTrend = tempLast - tempFirst;
let tempScore = 100;
if (tempTrend > 2.0)       tempScore -= 40;  // fast rising
else if (tempTrend > 1.0)  tempScore -= 25;
else if (tempTrend > 0.5)  tempScore -= 15;
if (tempMean > 7)          tempScore -= 20;  // running hot
else if (tempMean > 6)     tempScore -= 10;
tempScore = Math.max(0, tempScore);

// --- Energy efficiency score (0-100) ---
let energyScore = 100;
if (energyMean >= 4.0)      energyScore = 10;
else if (energyMean >= 3.5) energyScore = 30;
else if (energyMean >= 3.0) energyScore = 55;
else if (energyMean >= 2.5) energyScore = 75;

// --- Compressor health score (0-100) ---
const compOnPct = compTotal > 0 ? (compOn / compTotal) * 100 : 50;
let compScore = 100;
if (compOnPct > 85)       compScore = 20;  // running almost continuously
else if (compOnPct > 70)  compScore = 50;
else if (compOnPct > 60)  compScore = 75;
else if (compOnPct < 15)  compScore = 60;  // almost never running

// --- Overall maintenance score (0-100, higher = more urgent) ---
const maintenanceScore = Math.round(
    (100 - tempScore)   * 0.35 +
    (100 - energyScore) * 0.35 +
    (100 - compScore)   * 0.30
);

let priority, recommendation;
if (maintenanceScore < 20)      { priority = 'low';      recommendation = 'Normal operation - routine maintenance only'; }
else if (maintenanceScore < 40) { priority = 'low';      recommendation = 'Monitor trends - no immediate action needed'; }
else if (maintenanceScore < 60) { priority = 'medium';   recommendation = 'Schedule inspection within 2 weeks'; }
else if (maintenanceScore < 80) { priority = 'high';     recommendation = 'Schedule maintenance within 48 hours'; }
else                            { priority = 'critical'; recommendation = 'Immediate maintenance required - equipment degradation detected'; }

msg.payload = {
    unitId, maintenanceScore, priority, recommendation,
    temperatureStability: tempScore,
    energyEfficiency: energyScore,
    compressorHealth: compScore,
    timestamp: new Date().toISOString(),
    details: {
        tempTrend: tempTrend > 0.3 ? 'rising' : tempTrend < -0.3 ? 'falling' : 'stable',
        avgTemp: Math.round(tempMean * 10) / 10,
        avgEnergy: Math.round(energyMean * 10) / 10,
        compressorOnPct: Math.round(compOnPct)
    }
};
return msg;

const a = msg.payload;
msg.payload = {
    features: {
        maintenance: { properties: {
            score: a.maintenanceScore,
            temperatureStability: a.temperatureStability,
            energyEfficiency: a.energyEfficiency,
            compressorHealth: a.compressorHealth,
            recommendation: a.recommendation,
            priority: a.priority,
            lastCalculated: a.timestamp
        }},
        status: { properties: {
            healthScore: Math.round((a.temperatureStability + a.energyEfficiency + a.compressorHealth) / 3),
            health: a.priority === 'critical' ? 'critical' : a.priority === 'high' ? 'attention' : 'healthy'
        }}
    }
};
msg.url = `http://ditto-gateway:8080/api/2/things/org.eclipse.ditto:${a.unitId}`;
msg.method = 'PATCH';
msg.headers = { 'Content-Type': 'application/merge-patch+json', 'x-ditto-pre-authenticated': 'nginx:nodered' };
return msg;

const a = msg.payload;
if (a.maintenanceScore >= 60) return msg;
return null;

const a = msg.payload;
const cooldownMs = 30 * 60 * 1000;
const key = `pm_${a.unitId}`;
const lastSent = context.get(key) || 0;
const now = Date.now();
if (now - lastSent < cooldownMs) { node.debug(`PM cooldown active for ${a.unitId}`); return null; }
context.set(key, now);
return msg;

const a = msg.payload;
msg.payload = [
    { score: a.maintenanceScore, message: a.recommendation },
    { unitId: a.unitId, priority: a.priority }
];
return msg;

const a = msg.payload;
const priorityIcon = a.priority === 'critical' ? '🔴 CRITICAL' : a.priority === 'high' ? '🟠 HIGH' : '🟡 MEDIUM';
const ts = new Date(a.timestamp).toLocaleString('en-IN', { timeZone: 'Asia/Kolkata' });

msg.topic = `[Smart Cold Storage] ${priorityIcon} Predictive Maintenance - ${a.unitId} (Score: ${a.maintenanceScore}/100)`;

msg.payload = `Smart Cold Storage - Predictive Maintenance Alert
=====================================================

Unit      : ${a.unitId}
Priority  : ${priorityIcon}
Maint Score: ${a.maintenanceScore} / 100
Time (IST): ${ts}

Health Breakdown:
  Temperature Stability : ${a.temperatureStability}/100
  Energy Efficiency     : ${a.energyEfficiency}/100
  Compressor Health     : ${a.compressorHealth}/100

Trend Details:
  Temperature Trend : ${a.details.tempTrend}  (avg ${a.details.avgTemp}°C)
  Energy Consumption: avg ${a.details.avgEnergy} kW
  Compressor ON     : ${a.details.compressorOnPct}% of the time

Recommendation:
  ${a.recommendation}

=====================================================
-- Smart Cold Storage Predictive Maintenance System`;

return msg;
